class Solution {
public:
    int flipLights(int n, int presses) {
        n = min(n, 6);
        set<int> states;
        for (int mask = 0; mask < 16; ++mask) {
            int used = __builtin_popcount((unsigned)mask);
            if (used > presses || (presses - used) % 2 != 0) continue;
            int state = (1 << n) - 1;
            for (int i = 0; i < n; ++i) {
                bool flip = (mask & 1) != 0;
                if ((mask & 2) && (i + 1) % 2 == 0) flip = !flip;
                if ((mask & 4) && (i + 1) % 2 == 1) flip = !flip;
                if ((mask & 8) && i % 3 == 0) flip = !flip;
                if (flip) state ^= 1 << i;
            }
            states.insert(state);
        }
        return states.size();
    }
};
